contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: try calling play with a provided amount
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // observe before state
        uint pot_before = c.pot(); if (__ESBMC_reverted()) return;
        address bank_before = c.bank(); if (__ESBMC_reverted()) return;

        // attempt the call and record whether it reverted
        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after state
        uint pot_after = c.pot(); if (__ESBMC_reverted()) return;
        address bank_after = c.bank(); if (__ESBMC_reverted()) return;

        // General invariant: bank never changes; if call succeeded and amount == TICKET_AMOUNT (10)
        // then pot either increased by amount or became zero. For other cases (reverted or wrong amount)
        // we only require bank unchanged.
        assert(
            bank_after == bank_before
            && (
                // if call succeeded with exact ticket amount, enforce the two possible pot outcomes
                (!reverted && amount == 10) ? (
                    (pot_after == pot_before + amount) || (pot_after == 0)
                ) : true
            )
        );
    }

    // allow receiving Ether from C during play
    receive() external payable {}
}

